const CLOCK_BASE = Date.UTC(2026, 10, 2, 7, 15, 0);

export function now() {
    return CLOCK_BASE + performance.now();
}

export function mulberry32(seed) {
    let state = seed >>> 0;
    return function () {
        let t = (state = (state + 0x6d2b79f5) >>> 0);
        t = Math.imul(t ^ (t >>> 15), t | 1);
        t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
        return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    };
}

export function hashString(text) {
    let hash = 0x811c9dc5;
    for (let i = 0; i < text.length; i++)
        hash = Math.imul(hash ^ text.charCodeAt(i), 0x01000193);
    return hash >>> 0;
}


export function mark(name) {
    try {
        performance.mark("adtag-" + name);
    } catch (e) {}
}

// Yields to the promise jobs that are already queued. A real ad tag yields
// to the event loop here; this one stays in microtasks, so that a page load's
// ad work happens before the benchmark step ends (the page loads run as
// synchronous steps, harness/steps.mjs).
export function nextMicrotask() {
    return Promise.resolve();
}

// A script the page has preloaded (window.__portal.runScript, see the
// page runtime) runs right away instead of being inserted and loaded.
export function loadScript(src) {
    if (window.__portal?.runScript?.(src))
        return Promise.resolve(true);
    return new Promise((resolve) => {
        const script = document.createElement("script");
        script.async = true;
        script.src = src;
        script.onload = () => resolve(true);
        script.onerror = () => resolve(false);
        document.head.appendChild(script);
    });
}

export function runSafe(callback) {
    return function (...args) {
        try {
            return callback.apply(this, args);
        } catch (error) {
            console.error("adtag:", error);
            return undefined;
        }
    };
}
